a<-commandArgs(TRUE);root<-normalizePath(a[1]);dest<-a[2];source(file.path(root,"R/count_qc.R"));x<-read.csv(file.path(root,"fixtures/synthetic_counts.csv"),fileEncoding="UTF-8-BOM");z<-do.call(rbind,lapply(seq_len(nrow(x)),function(i)metrics(x$a[i],x$b[i],x$c[i],x$d[i])));stopifnot(all(z[,"N"]==1000),all(is.na(z[3,c("ROR","PRR","LCL","UCL")])));bad<-try(metrics(-1,2,3,4),silent=TRUE);stopifnot(inherits(bad,"try-error"));write.csv(data.frame(synthetic_id=x$synthetic_id,z),dest,row.names=FALSE);cat("R_SYNTHETIC_CHECKS_PASS\n");print(sessionInfo())
